    [Parameter] public int Id { get; set; }

    private bool _isLoading = true;
    private string? _errorMessage;
    private WorkOrderDetailDto? _workOrder;
    private BOMHeaderDetailDto? _activeBOM;
    private bool _canComplete = true;
    private ItemListDto? _itemDetails;
    private List<BOMUsageDto> _bomUsages = new();

    private List<WorkOrderListDto> _allWorkOrders = new();
    private List<WorkOrderListDto> _childWorkOrders = new();
    private List<PurchaseOrderListDto> _allPurchaseOrders = new();

    private Dictionary<string, WorkOrderListDto> _childWOsByItemCode = new();
    private Dictionary<string, PurchaseOrderListDto> _purchaseOrdersByItemCode = new();
    private Dictionary<string, decimal> _itemStocks = new();
    private Dictionary<int, bool> _childProducibleMap = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }
    private async Task LoadDataAsync()
    {
        _isLoading = true;
        _errorMessage = null;

        try
        {
            // 1. Fetch work order details
            var woResult = await WorkOrderService.GetByIdAsync(Id);
            if (!woResult.Success)
            {
                _errorMessage = woResult.Message;
                return;
            }
            _workOrder = woResult.Data;

            // 2. Fetch all work orders for hierarchy linking
            var allWoResult = await WorkOrderService.GetAllAsync();
            if (allWoResult.Success)
            {
                _allWorkOrders = allWoResult.Data.ToList();
                _childWorkOrders = _allWorkOrders.Where(w => w.ParentWorkOrderNo == _workOrder.WorkOrderNo).ToList();
                _childWOsByItemCode = _childWorkOrders.ToDictionary(w => w.ItemCode, w => w);
            }

            // 3. Fetch purchase orders
            var poResult = await PurchaseOrderService.GetAllAsync();
            if (poResult.Success)
            {
                _allPurchaseOrders = poResult.Data.ToList();
                _purchaseOrdersByItemCode = _allPurchaseOrders
                    .Where(p => p.RelatedWorkOrderNo == _workOrder.WorkOrderNo)
                    .ToDictionary(p => p.ItemCode, p => p);
            }

            // 4. Fetch Item Specifications
            var itemResult = await ItemService.GetAllAsync();
            if (itemResult.Success)
            {
                _itemDetails = itemResult.Data.FirstOrDefault(i => i.ItemCode == _workOrder.ItemCode);
            }

            // 5. Fetch Where-Used BOM Usages
            var usagesResult = await BOMService.GetBOMUsagesByItemCodeAsync(_workOrder.ItemCode);
            if (usagesResult.Success)
            {
                _bomUsages = usagesResult.Data.ToList();
            }

            // 6. Load BOM details
            var bomListResult = await BOMService.GetAllAsync();
            if (bomListResult.Success)
            {
                int? targetBOMHeaderId = _workOrder.BOMHeaderId;
                if (!targetBOMHeaderId.HasValue)
                {
                    var activeBOMHeader = bomListResult.Data.FirstOrDefault(b => b.ParentItemCode == _workOrder.ItemCode && b.IsActive);
                    targetBOMHeaderId = activeBOMHeader?.Id;
                }

                if (targetBOMHeaderId.HasValue)
                {
                    var bomDetailResult = await BOMService.GetByIdAsync(targetBOMHeaderId.Value);
                    if (bomDetailResult.Success)
                    {
                        _activeBOM = bomDetailResult.Data;

                        // Fetch stocks of child components
                        if (itemResult.Success && _activeBOM.Lines != null)
                        {
                            var childCodes = _activeBOM.Lines.Select(l => l.ChildItemCode).ToList();
                            _itemStocks = itemResult.Data
                                .Where(i => childCodes.Contains(i.ItemCode))
                                .ToDictionary(i => i.ItemCode, i => i.StockQuantity);
                        }
                    }
                }
            }

            // 7. Evaluate if completion is possible (must be status Released and all stocks must be sufficient)
            CheckCompletionStatus();

            // 8. Evaluate if child work orders can be completed
            _childProducibleMap.Clear();
            if (itemResult.Success && bomListResult.Success)
            {
                var stockDict = itemResult.Data.ToDictionary(i => i.ItemCode, i => i.StockQuantity);
                var activeBOMs = bomListResult.Data.Where(b => b.IsActive).ToList();

                foreach (var child in _childWorkOrders.Where(c => c.Status == WorkOrderStatus.Released))
                {
                    var activeBOM = activeBOMs.FirstOrDefault(b => b.ParentItemCode == child.ItemCode);
                    if (activeBOM == null)
                    {
                        _childProducibleMap[child.Id] = false;
                        continue;
                    }

                    var bomDetailResult = await BOMService.GetByIdAsync(activeBOM.Id);
                    if (bomDetailResult.Success && bomDetailResult.Data.Lines != null)
                    {
                        bool canBeCompleted = true;
                        foreach (var line in bomDetailResult.Data.Lines)
                        {
                            decimal neededQty = (line.Quantity * child.TargetQuantity) / bomDetailResult.Data.BaseQuantity;
                            if (line.ScrapRate > 0)
                            {
                                neededQty = neededQty * (1 + line.ScrapRate / 100);
                            }

                            stockDict.TryGetValue(line.ChildItemCode, out var currentStock);
                            if (currentStock < neededQty)
                            {
                                canBeCompleted = false;
                                break;
                            }
                        }
                        _childProducibleMap[child.Id] = canBeCompleted;
                    }
                    else
                    {
                        _childProducibleMap[child.Id] = false;
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _errorMessage = $"Veriler yüklenirken hata oluştu: {ex.Message}";
        }
        finally
        {
            _isLoading = false;
        }
    }

    private void CheckCompletionStatus()
    {
        _canComplete = true;
        if (_activeBOM == null || _activeBOM.Lines == null)
        {
            _canComplete = false;
            return;
        }

        foreach (var line in _activeBOM.Lines)
        {
            var totalNeeded = CalculateNeededQuantity(line.Quantity, line.ScrapRate);
            _itemStocks.TryGetValue(line.ChildItemCode, out var currentStock);
            if (currentStock < totalNeeded)
            {
                _canComplete = false;
                break;
            }
        }
    }

    private decimal CalculateNeededQuantity(decimal unitQty, decimal scrapRate)
    {
        if (_activeBOM == null || _activeBOM.BaseQuantity == 0 || _workOrder == null)
            return 0;

        decimal qty = (unitQty * _workOrder.TargetQuantity) / _activeBOM.BaseQuantity;
        if (scrapRate > 0)
        {
            qty = qty * (1 + scrapRate / 100);
        }
        return qty;
    }

    private int? GetParentWorkOrderId(string parentWoNo)
    {
        return _allWorkOrders.FirstOrDefault(w => w.WorkOrderNo == parentWoNo)?.Id;
    }

    private void NavigateToDetail(int id)
    {
        Navigation.NavigateTo($"/workorders/details/{id}", forceLoad: true);
    }

    private async Task UpdateStatusAsync(WorkOrderStatus status)
    {
        if (_workOrder == null) return;
        _isLoading = true;
        try
        {
            var result = await WorkOrderService.UpdateStatusAsync(_workOrder.Id, status);
            if (result.Success)
            {
                ToastService.ShowSuccess(result.Message);
                await LoadDataAsync();
            }
            else
            {
                _errorMessage = result.Message;
                ToastService.ShowError(result.Message);
            }
        }
        catch (Exception ex)
        {
            _errorMessage = $"Statü güncellenirken hata oluştu: {ex.Message}";
            ToastService.ShowError(_errorMessage);
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task UpdateChildStatusAsync(int id, WorkOrderStatus status)
    {
        _isLoading = true;
        try
        {
            var result = await WorkOrderService.UpdateStatusAsync(id, status);
            if (result.Success)
            {
                ToastService.ShowSuccess(result.Message);
                await LoadDataAsync();
            }
            else
            {
                ToastService.ShowError(result.Message);
            }
        }
        catch (Exception ex)
        {
            ToastService.ShowError($"Alt iş emri statüsü güncellenirken hata oluştu: {ex.Message}");
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task CreateChildWorkOrderAsync(string childItemCode, decimal deficit)
    {
        if (_workOrder == null) return;
        _isLoading = true;
        try
        {
            var childWoNo = $"WO-{DateTime.Now:yyyyMMdd}-{new Random().Next(1000, 9999)}";
            var createDto = new WorkOrderCreateDto
            {
                WorkOrderNo = childWoNo,
                ParentWorkOrderNo = _workOrder.WorkOrderNo,
                ItemCode = childItemCode,
                TargetQuantity = deficit
            };

            var result = await WorkOrderService.AddAsync(createDto);
            if (result.Success)
            {
                ToastService.ShowSuccess($"Alt iş emri ({childWoNo}) taslak olarak oluşturuldu.");
                await LoadDataAsync();
            }
            else
            {
                ToastService.ShowError(result.Message);
            }
        }
        catch (Exception ex)
        {
            ToastService.ShowError($"Alt iş emri oluşturulurken hata: {ex.Message}");
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task CreatePurchaseOrderAsync(string childItemCode, decimal deficit)
    {
        if (_workOrder == null) return;
        _isLoading = true;
        try
        {
            var poNo = $"PO-{DateTime.Now:yyyyMMdd}-{new Random().Next(1000, 9999)}";
            var createDto = new PurchaseOrderCreateDto
            {
                PurchaseOrderNo = poNo,
                ItemCode = childItemCode,
                Quantity = deficit,
                RelatedWorkOrderNo = _workOrder.WorkOrderNo,
                Notes = $"{_workOrder.WorkOrderNo} nolu iş emri için otomatik temin emri"
            };

            var result = await PurchaseOrderService.AddAsync(createDto);
            if (result.Success)
            {
                ToastService.ShowSuccess($"Temin emri ({poNo}) taslak olarak oluşturuldu.");
                await LoadDataAsync();
            }
            else
            {
                ToastService.ShowError(result.Message);
            }
        }
        catch (Exception ex)
        {
            ToastService.ShowError($"Temin emri oluşturulurken hata: {ex.Message}");
        }
        finally
        {
            _isLoading = false;
        }
    }

